const pako = await import("https://esm.run/pako");
const res = await tool.fetch_url({ url: "https://cdn.ymaws.com/www.aav.org/resource/collection/2E4858A3-6F5E-42C1-B689-3122A9CD832F/Budgies-AAV-flat.pdf" });

// Let's inspect how streams are defined in the PDF
const raw = res.body;
console.log("Raw length:", raw.length);

// Extract text using regex for standard PDF operators like Tj and TJ
// Let's see if there are uncompressed text streams or compressed streams
let extractedTexts = [];
const streamRegex = /stream\r?\n([\s\S]*?)\r?\nendstream/g;
let match;
let count = 0;
while ((match = streamRegex.exec(raw)) !== null) {
  count++;
  const streamData = match[1];
  const u8 = new Uint8Array(streamData.length);
  for (let i = 0; i < streamData.length; i++) {
    u8[i] = streamData.charCodeAt(i) & 0xff;
  }
  try {
    const decompressed = pako.inflate(u8);
    const decStr = new TextDecoder('utf-8', { fatal: false }).decode(decompressed);
    // Find text inside parentheses before Tj or [(...)] TJ
    const tjMatches = decStr.match(/\((.*?)\)\s*Tj/g);
    if (tjMatches) {
      extractedTexts.push(tjMatches.map(m => m.replace(/^\(|\)\s*Tj$/g, '')).join(' '));
    }
    const tjArrayMatches = decStr.match(/\[(.*?)\]\s*TJ/g);
    if (tjArrayMatches) {
      for (const arr of tjArrayMatches) {
        const parts = arr.match(/\((.*?)\)/g);
        if (parts) {
          extractedTexts.push(parts.map(p => p.slice(1, -1)).join(''));
        }
      }
    }
  } catch (e) {
    // Not a valid zlib stream or different encoding
  }
}
console.log("Found streams:", count, "Extracted text blocks:", extractedTexts.length);
console.log("Sample text extracted:", extractedTexts.join(' ').slice(0, 500));

