const tabId = 725789915;
await tool.navigate({ tabId, url: "https://www.aav.org/page/birdownerbrochures" });
await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 15000 });

const brochures = await browserjs(tabId, () => {
  const links = Array.from(document.querySelectorAll('a')).map(a => ({
    text: a.innerText.trim().replace(/\s+/g, ' '),
    href: a.href
  })).filter(l => l.href.includes('.pdf') || (l.text.length > 3 && !l.href.includes('javascript')));

  // also get all headings and text blocks
  const headings = Array.from(document.querySelectorAll('h1, h2, h3, h4, strong, p')).map(e => e.innerText.trim()).filter(t => t.length > 5);

  return {
    title: document.title,
    links: links.filter(l => l.href.includes('pdf') || l.href.includes('collection')),
    headings: headings.slice(0, 40)
  };
});

console.log("Brochures page title:", brochures.title);
console.log("PDF Links found:", brochures.links);
console.log("Headings/text:", brochures.headings);

