const pdfjs = await import("https://esm.run/pdfjs-dist@3.11.174");
pdfjs.default.GlobalWorkerOptions.workerSrc = "https://esm.run/pdfjs-dist@3.11.174/build/pdf.worker.min.js";

async function extractPdfText(url) {
  const res = await tool.fetch_url({ url });
  const uint8 = new Uint8Array(res.body.length);
  for (let i = 0; i < res.body.length; i++) {
    uint8[i] = res.body.charCodeAt(i) & 0xff;
  }
  const loadingTask = pdfjs.default.getDocument({ data: uint8 });
  const doc = await loadingTask.promise;
  let fullText = "";
  for (let p = 1; p <= doc.numPages; p++) {
    const page = await doc.getPage(p);
    const content = await page.getTextContent();
    const pageText = content.items.map(it => it.str).join(" ");
    fullText += `\n--- PAGE ${p} ---\n` + pageText;
  }
  return { numPages: doc.numPages, text: fullText };
}

const budgieData = await extractPdfText("https://cdn.ymaws.com/www.aav.org/resource/collection/2E4858A3-6F5E-42C1-B689-3122A9CD832F/Budgies-AAV-flat.pdf");
console.log("Budgie PDF extracted, pages:", budgieData.numPages);
console.log("Snippet:", budgieData.text.slice(0, 1500));

