const tabId = 725789915;
const result = await browserjs(tabId, async () => {
  const url = "https://cdn.ymaws.com/www.aav.org/resource/collection/2E4858A3-6F5E-42C1-B689-3122A9CD832F/Budgies-AAV-flat.pdf";
  const r = await fetch(url);
  const buf = await r.arrayBuffer();

  // Load pdfjs from cdnjs in the page
  if (!window.pdfjsLib) {
    await new Promise((resolve, reject) => {
      const s = document.createElement('script');
      s.src = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js";
      s.onload = resolve;
      s.onerror = reject;
      document.head.appendChild(s);
    });
  }
  window.pdfjsLib.GlobalWorkerOptions.workerSrc = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";

  const doc = await window.pdfjsLib.getDocument({ data: buf }).promise;
  let fullText = "";
  for (let i = 1; i <= doc.numPages; i++) {
    const page = await doc.getPage(i);
    const content = await page.getTextContent();
    const text = content.items.map(item => item.str).join(" ");
    fullText += `\n=== PAGE ${i} ===\n` + text;
  }
  return {
    numPages: doc.numPages,
    textLength: fullText.length,
    snippet: fullText.slice(0, 1500)
  };
});

console.log("PDF parsed inside page:", result);

