  { name: "Ducks", url: "https://cdn.ymaws.com/www.aav.org/resource/collection/AE20E93E-0F61-4C20-AB88-E237BD795B43/AAV_Caring_for_Ducks2022.pdf" }
];

const results = await browserjs(tabId, async (brochures) => {
  if (!window.pdfjsLib) {
    await new Promise((resolve, reject) => {
