      s.onload = resolve;
      s.onerror = reject;
      document.head.appendChild(s);
    });
    window.pdfjsLib.GlobalWorkerOptions.workerSrc = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";
  }

  const extracted = [];
  for (const b of brochures) {
    try {
      const r = await fetch(b.url);
      if (!r.ok) {
        extracted.push({ name: b.name, url: b.url, error: `HTTP ${r.status}` });
        continue;
      }
      const buf = await r.arrayBuffer();
      const doc = await window.pdfjsLib.getDocument({ data: buf }).promise;
      let text = "";
      for (let p = 1; p <= doc.numPages; p++) {
        const page = await doc.getPage(p);
        const tc = await page.getTextContent();
        text += tc.items.map(i => i.str).join(" ") + "\n";
      }
      extracted.push({
        name: b.name,
        url: b.url,
        numPages: doc.numPages,
        title: text.split("\n")[0]?.trim() || b.name,
        textSample: text.slice(0, 1000),
        headings: (text.match(/([A-Z][A-Za-z0-9\s\?]{3,40}\?)/g) || []).slice(0, 10),
        textLength: text.length
      });
    } catch (e) {
      extracted.push({ name: b.name, url: b.url, error: e.message });
    }
  }
  return extracted;
}, aavBrochures);

console.log("Extraction results:", JSON.stringify(results, null, 2));

