const tabId = 725789916;

const urlsToTest = [
  "https://vcahospitals.com/know-your-pet/budgies-general-care",
  "https://vcahospitals.com/know-your-pet/cockatiels-general-care",
  "https://vcahospitals.com/know-your-pet/canaries-general-care",
  "https://vcahospitals.com/know-your-pet/finches-general-care",
  "https://vcahospitals.com/know-your-pet/doves-and-pigeons-general-care",
  "https://vcahospitals.com/know-your-pet/first-aid-for-birds",
  "https://vcahospitals.com/know-your-pet/recognizing-the-signs-of-illness-in-pet-birds",
  "https://vcahospitals.com/know-your-pet/psittacosis-in-birds",
  "https://lafeber.com/pet-birds/species/cockatiel/",
  "https://lafeber.com/pet-birds/species/canary/",
  "https://lafeber.com/pet-birds/bird-first-aid/",
  "https://lafeber.com/pet-birds/bird-emergency-kit/"
];

const results = [];
for (const u of urlsToTest) {
  try {
    await tool.navigate({ tabId, url: u });
    const waitRes = await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });
    const data = await browserjs(tabId, () => {
      return {
        title: document.title,
        h1: document.querySelector('h1')?.innerText?.trim(),
        hasPrint: !!document.querySelector('button[onclick*="print"], a[href*="print"], .print-icon, [aria-label*="print" i]'),
        snippet: document.body.innerText.slice(0, 500).replace(/\s+/g, ' ')
      };
    });
    results.push({ url: u, title: data.h1 || data.title, hasPrint: data.hasPrint, snippet: data.snippet });
  } catch (e) {
    results.push({ url: u, error: e.message });
  }
}

console.log("VCA & Lafeber test results:", JSON.stringify(results, null, 2));

