const tabId = 725789916;

const vcaUrls = [
  "https://vcahospitals.com/know-your-pet/budgies---general",
  "https://vcahospitals.com/know-your-pet/cockatiels---general-information",
  "https://vcahospitals.com/know-your-pet/canaries---general",
  "https://vcahospitals.com/know-your-pet/finches---general",
  "https://vcahospitals.com/know-your-pet/lovebirds---general",
  "https://vcahospitals.com/know-your-pet/macaws---general"
];

const results = [];
for (const u of vcaUrls) {
  await tool.navigate({ tabId, url: u });
  await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 5000 });
  const data = await browserjs(tabId, () => {
    const h1 = document.querySelector('h1')?.innerText?.trim();
    const authors = Array.from(document.querySelectorAll('p, div')).find(el => el.innerText && el.innerText.includes('DVM'))?.innerText?.trim();
    const hasPrint = Array.from(document.querySelectorAll('a, button, span')).some(el => el.innerText && el.innerText.toLowerCase().includes('print'));
    const headings = Array.from(document.querySelectorAll('h2, h3, h4')).map(h => h.innerText.trim()).filter(h => h.length > 2);
    return {
      title: h1 || document.title,
      authors: authors?.slice(0, 100),
      hasPrint,
      headings: headings.slice(0, 8),
      textSnippet: document.body.innerText.slice(0, 600).replace(/\s+/g, ' ')
    };
  });
  results.push({ url: u, ...data });
}

console.log("VCA species articles:", JSON.stringify(results, null, 2));

