const tabId = 725789915;

const cockatielRes = await browserjs(tabId, async () => {
  const url = "https://cdn.ymaws.com/www.aav.org/resource/collection/2E4858A3-6F5E-42C1-B689-3122A9CD832F/Cockatiel-AAV-flat.pdf";
  const r = await fetch(url);
  const buf = await r.arrayBuffer();
  const doc = await window.pdfjsLib.getDocument({ data: buf }).promise;
  let text = "";
  for (let p = 1; p <= doc.numPages; p++) {
    const page = await doc.getPage(p);
    const tc = await page.getTextContent();
    text += tc.items.map(i => i.str).join(" ") + "\n";
  }
  return {
    numPages: doc.numPages,
    textLength: text.length,
    fullText: text
  };
});

console.log("Cockatiel pages:", cockatielRes.numPages, "len:", cockatielRes.textLength);
console.log("Cockatiel text snippet:\n", cockatielRes.fullText.slice(0, 2000));

