  "https://www.avma.org/resources/pet-owners/emergency-care/pets-and-disasters",
  "https://www.cdc.gov/psittacosis/about/index.html",
  "https://healthtopics.vetmed.ucdavis.edu/health-topics/companion-avian",
  "https://www.merckvetmanual.com/bird-owners/routine-care-and-breeding-of-birds/routine-care-of-pet-birds",
  "https://www.mspca.org/angell_services/parakeet-care/",
  "https://www.mspca.org/angell_services/cockatiel-care/"
];

const results = [];
for (const u of urlsToTest) {
  try {
    await tool.navigate({ tabId, url: u });
    await tool.wait_for({ tabId, condition: "dom_settled", timeout_ms: 4000 });
    const data = await browserjs(tabId, () => {
      const h1 = document.querySelector('h1')?.innerText?.trim();
      return {
        title: h1 || document.title,
        docTitle: document.title,
        is404: document.title.includes("404") || (h1 && h1.includes("404")),
        snippet: document.body.innerText.slice(0, 400).replace(/\s+/g, ' ')
      };
    });
    results.push({ url: u, ...data });
  } catch (e) {
    results.push({ url: u, error: e.message });
  }
}

console.log("Candidate URLs test results:", JSON.stringify(results, null, 2));

