const tabId = 725789916;

const birdMentions = await browserjs(tabId, async () => {
  const url = window.location.href;
  const r = await fetch(url);
  const buf = await r.arrayBuffer();
  const doc = await window.pdfjsLib.getDocument({ data: buf }).promise;
  let matches = [];
  for (let p = 1; p <= doc.numPages; p++) {
    const page = await doc.getPage(p);
    const tc = await page.getTextContent();
    const text = tc.items.map(i => i.str).join(" ");
    if (/bird|avian|parrot|cage|feather/i.test(text)) {
      matches.push({ page: p, text: text });
    }
  }
  return matches;
});

console.log("AVMA PDF bird mentions on pages:", birdMentions.map(m => m.page));
if (birdMentions.length > 0) {
  console.log("Sample excerpt:", birdMentions[0].text.slice(0, 1000));
}

